-- V9__add_daily_order_sequence_and_order_number.sql
-- Add daily order sequence management and human-readable order numbers
--
-- This migration:
-- 1. Creates daily_order_sequence table for managing daily sequences (single shop BB)
-- 2. Adds order_number column to orders table
-- 3. Creates unique index on order_number
-- 4. Uses PostgreSQL GENERATED BY DEFAULT AS IDENTITY for compatibility

-- Create table for managing daily order sequences (BB shop only)
-- Uses pessimistic locking (SELECT FOR UPDATE) to ensure concurrency-safe generation
CREATE TABLE IF NOT EXISTS daily_order_sequence (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    date_key VARCHAR(8) NOT NULL UNIQUE,
    last_sequence INTEGER NOT NULL DEFAULT 0,

    -- date_key is unique since we have only one sequence per day
    CONSTRAINT uq_daily_order_sequence_date UNIQUE (date_key)
);

-- Index for quick lookups by date_key (optimization for queries)
CREATE INDEX IF NOT EXISTS idx_daily_order_sequence_date_key
    ON daily_order_sequence (date_key);

-- Add order_number column to orders table
-- Nullable initially to support existing orders
ALTER TABLE orders
    ADD COLUMN IF NOT EXISTS order_number VARCHAR(32);

-- Create unique index on order_number to ensure global uniqueness
-- Null values are excluded from unique constraints in PostgreSQL, so:
-- - NULL order_numbers do not violate the constraint
-- - Multiple NULL values are allowed (supports legacy orders)
-- - Non-null values must be unique
CREATE UNIQUE INDEX IF NOT EXISTS idx_orders_order_number
    ON orders (order_number) WHERE order_number IS NOT NULL;

-- Index for efficient lookups by order_number
CREATE INDEX IF NOT EXISTS idx_orders_order_number_lookup
    ON orders (order_number);

-- Optional: Add check constraint to validate order_number format
-- Pattern: BB-YYYYMMDD-XXXX (e.g., BB-20260515-0001)
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM information_schema.table_constraints
        WHERE constraint_name = 'orders_order_number_format_check'
          AND table_name = 'orders'
    ) THEN
        ALTER TABLE orders
        ADD CONSTRAINT orders_order_number_format_check
        CHECK (order_number IS NULL OR order_number ~ '^BB-\d{8}-\d{4}$');
    END IF;
END $$;


